from taf.gnb.oam.coam.vdu.releases.vduoam24r1 import vDuOAM24R1
from taf.gnb.oam.coam.vdu.utilities.use_m2m_parser import enforce_use_m2m_type
from taf.gnb.oam.coam.vdu.schemas.cp_config_licensed.get_active_trace_streams_v1 import UplaneTraceStreamsInfoLICENSEDV1
from taf.gnb.oam.coam.vdu.schemas.trs_licensed.activate_upload_operation import (
    ActivateUploadOperationTrsLicensed,
)
from taf.gnb.oam.coam.vdu.schemas.trs_licensed.ip_traffic_capture_status import IPTrafficCaptureStatusTrsLicensed


class vDuOAM24R2(vDuOAM24R1):
    @enforce_use_m2m_type
    def remove_uplane_trace_stream(self, trace_id, timeout=30, use_m2m=True):
        if use_m2m:
            return self.asm_licensed.remove_uplane_trace_stream(trace_id=trace_id, timeout=timeout)
        else:
            return self.asm_v1.remove_uplane_trace_stream(trace_id=trace_id, timeout=timeout)

    @enforce_use_m2m_type
    def start_uplane_trace_stream(self, trace_type, target_component, nr_cell_dn_list, timeout=30, use_m2m=True):
        if use_m2m:
            self.asm_licensed.start_uplane_trace_stream(trace_type=trace_type,
                                                        target_component=target_component,
                                                        nr_cell_dn_list=nr_cell_dn_list,
                                                        timeout=timeout)
        else:
            self.asm_v1.start_uplane_trace_stream(trace_type=trace_type,
                                                  target_component=target_component,
                                                  nr_cell_dn_list=nr_cell_dn_list,
                                                  timeout=timeout)

    @enforce_use_m2m_type
    def get_active_trace_streams(self, timeout=30, use_m2m=True, raw=False):
        if use_m2m:
            res = self.asm_licensed.get_active_trace_streams(timeout=timeout)
        else:
            res = self.asm_v1.get_active_trace_streams(timeout=timeout)
        return res if raw else UplaneTraceStreamsInfoLICENSEDV1.from_object_dict(res)

    @enforce_use_m2m_type
    def stop_uplane_trace_stream(self, trace_id, timeout=30, use_m2m=True):
        if use_m2m:
            self.asm_licensed.stop_uplane_trace_stream(trace_id=trace_id, timeout=timeout)
        else:
            self.asm_v1.stop_uplane_trace_stream(trace_id=trace_id, timeout=timeout)

    @enforce_use_m2m_type
    def get_traces_activation_status(self, timeout=30, use_m2m=True):
        if use_m2m:
            res = self.asm_licensed.get_traces_activation_status(timeout=timeout)
        else:
            res = self.asm_v1.get_traces_activation_status(timeout=timeout)
        return res.value

    def start_ip_traffic_capture(self, capture_type, measurement_point, plane_type, pod_names, timeout=30):
        self.trs_licensed_v1.start_ip_traffic_capture(capture_type=capture_type,
                                                      plane_type=plane_type,
                                                      pod_names=pod_names,
                                                      measurement_point=measurement_point,
                                                      timeout=timeout)

    def stop_ip_traffic_capture(self, timeout=30):
        self.trs_licensed_v1.stop_ip_traffic_capture(timeout=timeout)

    def abort_ip_traffic_capture(self, timeout=30):
        return self.trs_licensed_v1.abort_ip_traffic_capture(timeout=timeout)

    def generate_ip_traffic_capture_files(self, credentials, timeout=30):
        return self.trs_licensed_v1.generate_ip_traffic_capture_files(credentials=credentials, timeout=timeout)

    def activate_file_upload_operation(self, timeout=30, raw=False):
        activate_operation = self.trs_licensed_v1.activate_file_upload_operation(timeout=timeout)
        return activate_operation if raw else ActivateUploadOperationTrsLicensed.from_object_dict(activate_operation)

    def get_file_upload_operation(self, operation_id, timeout=30):
        return self.trs_licensed_v1.get_file_upload_operation(operation_id=operation_id, timeout=timeout)

    def delete_file_upload_operation(self, timeout=30):
        self.trs_licensed_v1.delete_file_upload_operation(timeout=timeout)

    def upload_ip_traffic_capture_file(self, operation_id, file_name, timeout=30):
        return self.trs_licensed_v1.upload_ip_traffic_capture_file(operation_id=operation_id, file_name=file_name, timeout=timeout)

    def get_ip_traffic_capture_status(self, timeout=30, raw=False):
        res = self.trs_licensed_v1.get_ip_traffic_capture_status(timeout=timeout)
        return res if raw else IPTrafficCaptureStatusTrsLicensed.from_object_dict(res)
